def _tracker(rows) -> str:
    out = []
    for label, state, detail in rows:
        out.append(f'<div class="trk-row {state}"><span class="dot"></span><span class="lbl">{label}</span>'
                   f'<span class="det">{detail}</span></div>')
    return f'<div class="trk">{"".join(out)}</div>'


# ---- Step 1: quote ---------------------------------------------------------
def _step_quote():
    n = ss["nonce"]
    draft = ss["draft"]
    a = draft["account"]
    number_cfg = {f: st.column_config.NumberColumn(min_value=0, max_value=LARGE_NUMBER_MAX, step=1, format="%.2f")
                  for f in LARGE_NUMBER_FIELDS}
    _labels = {"STREETNAME": "Street", "CITY": "City", "COUNTY": "County", "STATE": "State", "ZIPCODE": "ZIP"}
    text_cfg = {f: st.column_config.TextColumn(_labels.get(f, f)) for f in TEXT_FIELDS}

    with st.form(key=f"quote_form_{n}", clear_on_submit=False):
        _sec("Policy")
        r1 = st.columns([2, 1, 1, 2])
        account_key = r1[0].text_input("Account key", value=a["Account Key"], placeholder="25M_1234")
        layer_name = r1[1].text_input("Layer", value=a["Layer Name"], placeholder="25M")
        underwriter = r1[2].text_input("Underwriter", value=a["Underwriter Initials"], placeholder="TR")
        lob = r1[3].text_input("Line of business", value=a["Line of Business"], placeholder="ANV_PacificPoint")
        r2 = st.columns(4)
        inception_date = r2[0].date_input("Inception", value=date.fromisoformat(a["Inception Date"]), format="DD/MM/YYYY")
        expiry_date = r2[1].date_input("Expiry", value=date.fromisoformat(a["Expiry Date"]), format="DD/MM/YYYY",
                                       help="Defaults to one year after today - change it to match the policy.")
        share_percent = r2[2].number_input("Share (%)", value=float(a["Share %"]), step=5.0, min_value=0.0,
                                           max_value=1000.0, format="%.2f",
                                           help="Participation as a percentage of the layer - 100% = full layer.")
        premium = r2[3].number_input("Premium", value=int(a["Premium"]), step=1000, min_value=0, max_value=LARGE_NUMBER_MAX)
        r3 = st.columns(4)
        policy_limit = r3[0].number_input("Policy limit", value=int(a["Policy Limit"]), step=100000, min_value=0, max_value=LARGE_NUMBER_MAX)
        attachment = r3[1].number_input("Attachment", value=int(a["Attachment"]), step=10000, min_value=0, max_value=LARGE_NUMBER_MAX)
        min_ded = r3[2].number_input("Minimum deductible", value=int(a["Min Ded"]), step=1000, min_value=0, max_value=LARGE_NUMBER_MAX)
        max_ded = r3[3].number_input("Maximum deductible", value=int(a["Max Ded"]), step=1000, min_value=0, max_value=LARGE_NUMBER_MAX)

        _sec("Locations")
        st.caption("One row per location. Dropdowns map to the RMS ATC codes. Street, city, state and ZIP are plain "
                   "text, so a leading-zero ZIP is never altered. You can paste straight from Excel.")
        seed_key = f"loc_seed_{n}"
        if seed_key not in ss:
            ss[seed_key] = _loc_frame(draft.get("locations"))
        edited = st.data_editor(
            ss[seed_key],
            column_config={
                **text_cfg, **number_cfg,
                "Construction": st.column_config.SelectboxColumn(options=options_list(CONSTRUCTION)),
                "Occupancy": st.column_config.SelectboxColumn(options=options_list(OCCUPANCY)),
                "Contents Damageability Grade": st.column_config.SelectboxColumn(options=options_list(CONTENTS_DAMAGE)),
                "Construction Quality": st.column_config.SelectboxColumn(options=options_list(CONSTRUCTION_QUALITY)),
                "Plan Irregularity": st.column_config.SelectboxColumn(options=options_list(PLAN_IRREGULARITY)),
                "Soft Story": st.column_config.SelectboxColumn(options=options_list(SOFT_STORY)),
                "Vertical Irregularity": st.column_config.SelectboxColumn(options=options_list(VERTICAL_IRREGULARITY)),
                "Cladding Type": st.column_config.SelectboxColumn(options=options_list(CLADDING_TYPE)),
                "Frame Bolted": st.column_config.SelectboxColumn(options=options_list(FRAME_BOLTED)),
                "Anchoring": st.column_config.SelectboxColumn(options=options_list(ANCHORING)),
                "Engineered Foundation": st.column_config.SelectboxColumn(options=options_list(ENGINEERED_FOUNDATION)),
                "Sprinkler Type": st.column_config.SelectboxColumn(options=options_list(SPRINKLER_TYPE)),
                "EQSL  Susceptibility": st.column_config.SelectboxColumn(options=options_list(SPRINKLER_LEAKAGE)),
                "EQSL Y/N": st.column_config.SelectboxColumn(options=["N", "Y"]),
                "Number of Buildings": st.column_config.NumberColumn(min_value=0, step=1),
                "Number of Stories": st.column_config.NumberColumn(min_value=0, step=1),
                "Year Built (YYYY)": st.column_config.NumberColumn(min_value=0, max_value=2100, step=1, format="%d"),
                "Year Upgraded (YYYY)": st.column_config.NumberColumn(min_value=0, max_value=2100, step=1, format="%d"),
            },
            num_rows="dynamic", hide_index=True, width="stretch", key=f"loc_editor_{n}",
        )
        b = st.columns([5, 1.2, 1.2, 2.4])
        b[0].caption("Changes are kept when you press Save draft, Check data or Geocode.")
        save_btn = b[1].form_submit_button("Save draft", width="stretch")
        check_btn = b[2].form_submit_button("Check data", width="stretch",
                                            help="Runs the preflight checks without geocoding anything.")
        go_btn = b[3].form_submit_button("Geocode and build files", type="primary", width="stretch")

    # ---- capture what is on screen ----
    draft["account"] = {
        "Account Key": account_key.strip(), "Layer Name": layer_name.strip(), "Underwriter Initials": underwriter.strip(),
        "Line of Business": lob.strip(), "Inception Date": inception_date.isoformat(),
        "Expiry Date": expiry_date.isoformat(), "Share %": float(share_percent), "Premium": premium,
        "Policy Limit": policy_limit, "Attachment": attachment, "Min Ded": min_ded, "Max Ded": max_ded}
    draft["locations"] = edited.to_dict("records")

    if save_btn:
        if _save():
            st.toast("Draft saved")
    pf_blocked = False
    if check_btn or go_btn:
        if _preflight is None:
            ss["preflight_issues"] = None
        else:
            issues = _preflight(_rms_account(draft["account"]), draft["locations"], inception_date, expiry_date)
            ss["preflight_issues"] = issues
            pf_blocked = any(i["level"] == "error" for i in issues)

    pf = ss.get("preflight_issues")
    if pf is not None:
        sm = _pf_summarize(pf)
        if sm["error"]:
            st.error(f"{sm['error']} problem(s) must be fixed before geocoding ({sm['warn']} warning(s)).")
        elif sm["warn"]:
            st.warning(f"Checks passed with {sm['warn']} warning(s) - worth a look, but you can continue.")
        else:
            st.success("Checks passed" + (f" ({sm['info']} note(s))." if sm["info"] else "."))
        if pf:
            with st.expander("Check details", expanded=bool(sm["error"] or sm["warn"])):
                st.markdown(_pf_markdown(pf))

    if go_btn and not pf_blocked:
        if not api_key:
            st.warning("Add the Location Intelligence key under 'Connection and settings' at the top (or save LI_API_KEY as a variable) to geocode.")
        elif not account_key.strip():
            st.warning("Enter an account key.")
        else:
            api = GeocodeApi(host.strip(), api_key, verify=verify_ssl)
            with st.spinner("Geocoding locations and building the RMS files..."):
                acc_df, loc_df, preview_rows, ok_count, total_count = geocode_and_build(
                    api, _rms_account(draft["account"]), edited)
            if total_count == 0:
                st.warning("No location has a street name - add at least one above.")
            else:
                for k in ("rms_import_job", "verify_result", "pipeline_state", "res_state", "verify_override"):
                    ss.pop(k, None)                # new files = a new run
                ss["acc_df"], ss["loc_df"], ss["preview_rows"] = acc_df, loc_df, preview_rows
                ss["geo_failed"], ss["geo_coarse"] = geocode_quality(preview_rows)
                ss["geo_ok"] = (ok_count, total_count)
                if ss.get("acct_id"):
                    STORE.clear_part(ss["acct_id"], "run")
                    STORE.clear_part(ss["acct_id"], "results")
                _save()
                _goto(S_GEO)
    elif go_btn and pf_blocked:
        st.error("Fix the items above, then try again. Nothing was sent to RMS.")


# ---- Step 2: geocode review ---------------------------------------------------
def _step_geocode():
    if "acc_df" not in ss:
        st.info("Complete the quote and press **Geocode and build files** first.")
        if st.button("Back to the quote", key="geo_back"):
            _goto(S_QUOTE)
        return
    acc_df, loc_df = ss["acc_df"], ss["loc_df"]
    preview_rows = ss.get("preview_rows", [])
    failed, coarse = ss.get("geo_failed") or [], ss.get("geo_coarse") or []
    total = len(preview_rows)
    ok = sum(1 for r in preview_rows if r.get("Latitude") not in (None, ""))
    tiv = _draft_tiv(ss["draft"])
    if _kpis:
        st.markdown(_kpis([
            ("Locations", f"{total:,}", "with a street address", NAVY),
            ("Geocoded", f"{ok:,} / {total:,}", "coordinates found", "#2E7D5B" if ok == total else "#B23A48"),
            ("Coarse match", f"{len(coarse):,}", "postcode level or worse", GOLD if coarse else "#2E7D5B"),
            ("Total TIV", _kfmt(tiv, True), "building + contents + BI", "#8A94A6")]), unsafe_allow_html=True)
    if failed:
        st.error(f"{len(failed)} location(s) did not geocode and have no coordinates in the LOC file: "
                 + "; ".join(f"row {g['row']} ({g['street'][:30]})" for g in failed[:8]) + (" ..." if len(failed) > 8 else "")
                 + ". Fix the address and rebuild, or let RMS geocode them in the next step.")
    if coarse:
        st.warning(f"{len(coarse)} location(s) only matched to postcode level or coarser: "
                   + "; ".join(f"row {g['row']} ({g['street'][:24]} - {g['why']})" for g in coarse[:6])
                   + (" ..." if len(coarse) > 6 else "") + ". Results for these are less precise.")

    preview_df = pd.DataFrame(preview_rows)
    if not preview_df.empty:
        map_df = preview_df.copy()
        map_df["Latitude"] = pd.to_numeric(map_df["Latitude"], errors="coerce")
        map_df["Longitude"] = pd.to_numeric(map_df["Longitude"], errors="coerce")
        map_df = map_df.dropna(subset=["Latitude", "Longitude"])
        _sec("Map")
        if not map_df.empty:
            map_df["Geocoded OK"] = ~map_df["Resolution Type"].astype(str).str.startswith("ERROR")
            map_df["fill_color"] = map_df.apply(lambda r: resolution_marker_color(r["Resolution Code"], r["Geocoded OK"]), axis=1)
            map_df["label"] = (map_df["STREETNAME"].astype(str) + ", " + map_df["CITY"].astype(str)
                               + " (" + map_df["State (resolved)"].astype(str) + ")")
            layer = pdk.Layer("ScatterplotLayer", data=map_df, get_position="[Longitude, Latitude]",
                              get_fill_color="fill_color", get_radius=250, radius_min_pixels=6, radius_max_pixels=18,
                              pickable=True, stroked=True, get_line_color=[255, 255, 255], line_width_min_pixels=1)
            view = pdk.ViewState(latitude=map_df["Latitude"].mean(), longitude=map_df["Longitude"].mean(),
                                 zoom=10 if len(map_df) > 1 else 13, pitch=0)
            deck = pdk.Deck(layers=[layer], initial_view_state=view, map_provider="carto", map_style="light",
                            tooltip={"html": "<b>{label}</b><br/>CRESTA: {CRESTA}<br/>{Resolution Type}",
                                     "style": {"backgroundColor": "#14304D", "color": "white"}})
            st.pydeck_chart(deck)
            st.markdown('<div class="legend">Marker colour = geocode precision'
                        '<span style="background:#228B22"></span>street level or better'
                        '<span style="background:#FFC107"></span>postcode / city'
                        '<span style="background:#DC3545"></span>county or coarser / failed'
                        '<span style="background:#800080"></span>ambiguous</div>', unsafe_allow_html=True)
        else:
            st.info("No location has valid coordinates to plot.")
        with st.expander("Geocode results"):
            st.dataframe(preview_df, width="stretch", hide_index=True)

    with st.expander("RMS import files (ACC / LOC)"):
        t1, t2 = st.tabs(["ACC", "LOC"])
        t1.dataframe(acc_df, width="stretch", hide_index=True)
        t2.dataframe(loc_df, width="stretch", hide_index=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        base = ss["draft"]["account"]["Account Key"] or "export"
        d1, d2 = st.columns(2)
        d1.download_button("Download ACC (.csv)", data=acc_df.to_csv(index=False).encode("utf-8"),
                           file_name=f"{base}_ACC_{stamp}.csv", mime="text/csv", width="stretch", key="dl_acc")
        d2.download_button("Download LOC (.csv)", data=loc_df.to_csv(index=False).encode("utf-8"),
                           file_name=f"{base}_LOC_{stamp}.csv", mime="text/csv", width="stretch", key="dl_loc")

    st.markdown("")
    n1, n2, _ = st.columns([1.2, 1.6, 5])
    if n1.button("Back", key="geo_prev", width="stretch"):
        _goto(S_QUOTE)
    if n2.button("Continue to RMS", type="primary", key="geo_next", width="stretch"):
        _goto(S_RUN)


# ---- Step 3: RMS run -------------------------------------------------------------
import math as _math


def _edm_eta(elapsed: float) -> float:
    """Estimated share (0-1) of the EDM build done after `elapsed` seconds. Eases toward ~97%, never reaches 100%
    until RMS confirms the EDM - so the bar keeps moving but never claims to be finished early."""
    return min(0.97, 1.0 - _math.exp(-max(elapsed, 0.0) / 100.0))


def _edm_with_progress(rms_api, edm_name: str, tick):
    """Same result as rms_api.get_or_create_edm(), but ticks once a second so a progress bar can move smoothly.
    Returns (exposure_id, diagnostic_message); exposure_id is '' on failure."""
    eid = rms_api.resolve_exposure_id(edm_name)
    if eid:
        return eid, ""
    url = (f"https://{rms_api.host}/riskmodeler/v1/datasources"
           f"?datasourcename={quote(edm_name)}&operation=CREATE")
    status, text, _h = rms_api._post(url, "")
    if status != 409 and not (200 <= status < 300):
        return "", (f"EDM CREATE request was rejected by RMS.\nURL: {url}\n"
                    f"HTTP status: {status}\nResponse: {text}")
    limit = RMS_EDM_WAIT_ATTEMPTS * RMS_EDM_WAIT_SECONDS
    t0 = time.time()
    last_check = 0.0
    while True:
        elapsed = time.time() - t0
        tick(elapsed)
        if elapsed - last_check >= RMS_EDM_WAIT_SECONDS:
            last_check = elapsed
            eid = rms_api.resolve_exposure_id(edm_name)
            if eid:
                return eid, ""
        if elapsed > limit:
            break
        time.sleep(1)
    return "", (f"RMS accepted the EDM create request (HTTP {status}), but the EDM never became findable. "
                f"Waited {int(limit)}s for '{edm_name}'.\nCreate response: {text}")


_IMP_OK = ("COMPLETED", "COMPLETE", "SUCCESS", "SUCCEEDED", "FINISHED", "DONE")
_IMP_BAD = ("FAILED", "ERROR", "CANCELLED", "CANCELED")


def _refresh_import(job) -> None:
    """One status check. If RMS reports no recognisable end state, fall back to what is actually in RMS:
    if every location is already there, the import is finished."""
    api = RmsImportApi(rms_import_host, rms_import_api_key, verify=rms_import_verify_ssl)
    status, url, raw = api.check_job_status_once(job["job_id"], cached_status_url=job.get("status_url", ""))
    job["status_url"] = url
    ss["import_seen"] = status
    if status in _IMP_OK:
        job["import_status"] = "COMPLETED"
    elif status in _IMP_BAD:
        job["import_status"] = "FAILED"
        ss["import_log"] = (raw or "")[:1500]
    elif "loc_df" in ss and job.get("portfolio_id"):
        try:
            verifier = ImportVerifier(rms_import_host, rms_import_api_key, verify=rms_import_verify_ssl)
            res = verify_location_count(verifier, job["exposure_id"], job["portfolio_id"], len(ss["loc_df"]))
            if res.get("match") and not res.get("error"):
                job["import_status"] = "COMPLETED"
                ss["import_seen"] = f"{status} (locations confirmed in RMS)"
        except Exception:                                           # noqa: BLE001
            pass


def _run_import(edm_name: str, account_key: str) -> None:
    """Create/resolve the EDM, make the portfolio, upload both files, submit the MRI import and poll it."""
    acc_bytes = ss["acc_df"].to_csv(index=False).encode("utf-8")
    loc_bytes = ss["loc_df"].to_csv(index=False).encode("utf-8")
    rms_api = RmsImportApi(rms_import_host.strip(), rms_import_api_key, verify=rms_import_verify_ssl)
    st.caption("Keep this page open while RMS builds the database - it usually takes a few minutes.")
    bar = st.progress(0.01, text="Starting import")
    _bar_last = [0.01]

    def bar_set(frac, text):
        _bar_last[0] = min(max(frac, 0.0), 1.0)
        bar.progress(_bar_last[0], text=text)

    def bar_stop(text):
        bar.progress(_bar_last[0], text=text)
    box = st.status("Starting import...", expanded=True)
    lines = []

    def log(msg):
        lines.append(msg)
        box.write(msg)
    try:
        box.update(label="Resolving or creating the EDM...")
        def tick(elapsed):
            mins, secs = divmod(int(elapsed), 60)
            bar_set(0.02 + 0.68 * _edm_eta(elapsed), f"Building the EDM in RMS  -  {mins}:{secs:02d} elapsed")
        log(f"Resolving EDM '{edm_name}'...")

        def wait_cb(attempt, total, name):
            box.update(label=f"Waiting for EDM '{name}' to build... ({attempt}/{total})")
        exposure_id, diag = _edm_with_progress(rms_api, edm_name, tick)
        if not exposure_id:
            log(f"Failed to resolve or create the EDM.\n{diag}")
            box.update(label="EDM creation failed", state="error")
            bar_stop("EDM creation failed")
            return
        log(f"EDM confirmed (exposureId {exposure_id})")
        bar_set(0.70, "EDM ready")
        box.update(label="Creating the portfolio...")
        bar_set(0.73, "Creating the portfolio")
        portfolio_id = rms_api.ensure_portfolio_by_identifier(exposure_id, account_key)
        log(f"Portfolio ready (portfolioId {portfolio_id})" if portfolio_id
            else "Could not create or resolve a portfolio - the import would target the EDM directly.")
        box.update(label="Uploading the files...")
        bar_set(0.79, "Uploading the ACC and LOC files")
        folder_ok, folder_id, acc_upload, loc_upload = rms_api.create_import_folder()
        if not folder_ok:
            log("Failed to create the import folder.")
            box.update(label="Import folder creation failed", state="error")
            bar_stop("Import folder creation failed")
            return
        acc_ok, acc_err = rms_api.upload_file_to_s3(acc_upload, acc_bytes)
        log(f"ACC upload: {'OK' if acc_ok else acc_err}")
        loc_ok, loc_err = rms_api.upload_file_to_s3(loc_upload, loc_bytes)
        log(f"LOC upload: {'OK' if loc_ok else loc_err}")
        if not (acc_ok and loc_ok):
            box.update(label="File upload failed", state="error")
            bar_stop("File upload failed")
            return
        box.update(label="Submitting the import job...")
        bar_set(0.86, "Submitting the import job")
        job_id, raw = rms_api.submit_import_job(folder_id, exposure_id, portfolio_id, currency="USD")
        if not job_id:
            log(f"Import job submission failed.\nRaw response: {raw[:500]}")
            box.update(label="Import job submission failed", state="error")
            bar_stop("Import job submission failed")
            return
        log(f"Import job submitted (jobId {job_id})")
        for k in ("verify_result", "pipeline_state", "res_state", "verify_override", "launch_error",
                  "run_stamp", "arch_hash"):
            ss.pop(k, None)                                     # a new import job is a new run -> new folder
        if ss.get("acct_id"):
            STORE.clear_part(ss["acct_id"], "results")
        ss["rms_import_job"] = {"job_id": job_id, "exposure_id": exposure_id, "portfolio_id": portfolio_id,
                                "edm_name": edm_name, "status_url": "", "import_status": "RUNNING"}
        _save()
        box.update(label="Waiting for the import to finish...")
        bar_set(0.88, "Waiting for RMS to finish the import")
        final, status_url = "UNKNOWN", ""
        for i in range(1, 13):
            time.sleep(5)
            final, status_url, _raw = rms_api.check_job_status_once(job_id, cached_status_url=status_url)
            log(f"Import status {i}/12: {final}")
            bar_set(0.88 + 0.12 * i / 12, f"Waiting for RMS to finish the import  -  check {i} of 12")
            if final in _IMP_OK or final in _IMP_BAD:
                break
        ss["rms_import_job"]["status_url"] = status_url
        if final in _IMP_OK:
            ss["rms_import_job"]["import_status"] = "COMPLETED"
            box.update(label="Import complete", state="complete")
            bar_set(1.0, "Import complete")
        elif final in _IMP_BAD:
            ss["rms_import_job"]["import_status"] = "FAILED"
            box.update(label="Import failed", state="error")
            bar_stop("Import failed in RMS")
        else:
            log("Still running - use 'Check import status' below.")
            box.update(label=f"Import still running ({final})", state="running")
        _save()
    except Exception as exc:                                       # noqa: BLE001
        if type(exc).__name__ in ("RerunException", "StopException"):
            raise
        log(f"Unexpected error: {exc}")
        box.update(label="Import stopped on an unexpected error", state="error")


def _verify_now(job) -> None:
    verifier = ImportVerifier(rms_import_host, rms_import_api_key, verify=rms_import_verify_ssl)
    ss["verify_result"] = verify_location_count(verifier, job["exposure_id"], job["portfolio_id"], len(ss["loc_df"]))


def _launch_pipeline(job) -> None:
    failed = ss.get("geo_failed") or []
    effective_skip = skip_prev_geocoded and not failed
    api = RmsAnalysisApi(rms_import_host, rms_import_api_key, verify=rms_import_verify_ssl)
    geo_job_id, raw = api.submit_geocode_job(job["edm_name"], job["portfolio_id"], geohaz_engine_type,
                                             geohaz_engine_version, effective_skip)
    if not geo_job_id:
        ss["launch_error"] = f"The geocode job could not be submitted.\n{raw[:500]}"
        return
    ss["launch_error"] = ""
    ss["pipeline_state"] = new_pipeline_state(job["edm_name"], job["portfolio_id"], rms_import_host, "",
                                              rms_import_verify_ssl, geo_job_id)
    _save()


def _pipeline_rows(job, pstate) -> list:
    imp = (job or {}).get("import_status", "")
    r_imp = ("done", "Complete") if imp == "COMPLETED" else ("fail", "Failed") if imp == "FAILED" \
        else ("act", "Running in RMS") if imp == "RUNNING" else ("pend", "Waiting")
    vr = ss.get("verify_result")
    if vr:
        if vr.get("error"):
            r_ver = ("fail", "Could not be checked")
        elif vr.get("match"):
            r_ver = ("done", f"{vr['actual']} of {vr['expected']} locations present")
        else:
            r_ver = ("done" if ss.get("verify_override") else "warn",
                     f"{vr.get('actual')} of {vr['expected']} locations" + (" (accepted)" if ss.get("verify_override") else ""))
    else:
        r_ver = ("act", "Checking...") if imp == "COMPLETED" and not ss.get("launch_error") else ("pend", "Waiting")
    rows = [("Create EDM and import", *r_imp), ("Verify locations", *r_ver)]
    stage = (pstate or {}).get("stage")
    order = ["geocode", "hazard", "analysis"]
    names = {"geocode": "Geocode", "hazard": "Hazard", "analysis": "Analysis"}
    cur = None
    if pstate:
        if stage == "done":
            cur = 3
        elif stage == "failed":
            cur = 2 if pstate.get("an_job_id") else 1 if pstate.get("haz_job_id") else 0
        else:
            cur = order.index(stage)
    for i, s in enumerate(order):
        if cur is None:
            rows.append((names[s], "pend", "Waiting"))
            continue
        status = pstate.get({"geocode": "geo_status", "hazard": "haz_status", "analysis": "an_status"}[s]) or ""
        if i < cur:
            rows.append((names[s], "done", status.title() or "Complete"))
        elif i == cur and stage == "failed":
            rows.append((names[s], "fail", status.title() or "Failed"))
        elif i == cur:
            rows.append((names[s], "act", status.title() or "Submitted"))
        else:
            rows.append((names[s], "pend", "Waiting"))
    return rows


def _step_run():
    if "acc_df" not in ss and not (ss.get("rms_import_job") or {}).get("recovered"):
        st.info("Build the ACC and LOC files first (steps 1 and 2).")
        if st.button("Back to the quote", key="run_back"):
            _goto(S_QUOTE)
        return
    job = ss.get("rms_import_job")
    acct_key = ss["draft"]["account"]["Account Key"]

    if job and job.get("recovered"):
        st.success(f"Loaded from RMS: EDM **{job['edm_name']}**. The import and analysis were done earlier, "
                   "so there is nothing to run here.")
        if st.button("View results", type="primary", key="rec_view"):
            ss["auto_pull"] = "res_state" not in ss
            _goto(S_RES)
        return

    if not job:
        edm_default = _edm_default(acct_key)
        edm_name = st.text_input("EDM name", value=edm_default, key=f"edm_name_{ss['nonce']}",
                                 help="Convention: EDM-ANV_<account key>_Y<yy>. An EDM that already exists is reused.")
        failed = ss.get("geo_failed") or []
        allow = True
        if failed:
            st.warning(f"{len(failed)} location(s) have no coordinates. RMS can geocode them during the analysis.")
            allow = st.checkbox("Import anyway and let RMS geocode them", value=False, key="allow_ungeo")
        c1, c2, _ = st.columns([2.2, 1.2, 4])
        go = c1.button("Import and run analysis", type="primary", width="stretch", key="run_go",
                       disabled=not allow)
        if c2.button("Back", width="stretch", key="run_prev"):
            _goto(S_GEO)
        st.caption("One click does the lot: creates the EDM and portfolio, uploads and imports the files, confirms every "
                   "location arrived, then runs geocode, hazard and the earthquake analysis.")
        if go:
            if not rms_import_api_key:
                st.warning("Add the Risk Data key under 'Connection and settings' at the top (or save RISKDATA_API_KEY as a variable).")
            elif not edm_name.strip():
                st.warning("Enter an EDM name.")
            else:
                _run_import(edm_name.strip(), acct_key.strip())
                st.rerun()
        return

    # ---- a job exists: drive it forward ----
    imp = job.get("import_status", "")
    if imp == "RUNNING":
        @st.fragment(run_every="5s")
        def _imp_watch():
            if not rms_import_api_key:
                st.warning("Add the Risk Data key under 'Connection and settings' at the top so the import can be checked.")
                return
            _refresh_import(job)
            if job.get("import_status") != "RUNNING":
                _save()
                st.rerun()
            st.info(f"Import job {job['job_id']} - RMS reports: {ss.get('import_seen') or 'no status yet'}. "
                    "Checking automatically every 5 seconds.")
        _imp_watch()
        with st.expander("Import looks finished in RMS but this has not moved?"):
            st.caption("Marks the import complete. The next step still confirms every location is present.")
            if st.button("Treat the import as complete", key="imp_force"):
                job["import_status"] = "COMPLETED"
                _save()
                st.rerun()
    elif imp == "FAILED":
        st.error("The import job failed in RMS.")
        if ss.get("import_log"):
            st.code(ss["import_log"], language=None)

    if imp == "COMPLETED" and not job.get("portfolio_id"):
        st.error("No portfolio was created during the import, so the analysis cannot run. Start over and retry.")
    elif imp == "COMPLETED":
        if "verify_result" not in ss:
            with st.spinner("Confirming every location arrived in RMS..."):
                _verify_now(job)
        vr = ss["verify_result"]
        if vr.get("error") or not vr.get("match"):
            if not ss.get("verify_override"):
                (st.error if vr.get("error") else st.warning)(vr["message"].strip())
                v1, v2, _ = st.columns([1.8, 1.4, 4])
                if v1.button("Continue anyway", type="primary", key="ver_ok"):
                    ss["verify_override"] = True
                    st.rerun()
                if v2.button("Check again", key="ver_again"):
                    ss.pop("verify_result", None)
                    st.rerun()
        ready = vr.get("match") or ss.get("verify_override")
        if ready and "pipeline_state" not in ss and not ss.get("launch_error"):
            with st.spinner("Submitting geocode, hazard and analysis..."):
                _launch_pipeline(job)
            st.rerun()
        if ss.get("launch_error"):
            st.error(ss["launch_error"])
            if st.button("Try again", key="launch_retry"):
                ss["launch_error"] = ""
                st.rerun()

    ps = ss.get("pipeline_state")
    active = bool(ps and ps.get("stage") not in ("done", "failed"))

    @st.fragment(run_every="5s" if active else None)
    def _live():
        state = ss.get("pipeline_state")
        prev = state["stage"] if state else None
        if state and state["stage"] not in ("done", "failed") and not rms_import_api_key:
            st.warning("Add the Risk Data key under 'Connection and settings' at the top to keep tracking this run.")
        elif state and state["stage"] not in ("done", "failed"):
            api = RmsAnalysisApi(rms_import_host, rms_import_api_key, verify=rms_import_verify_ssl)
            state = advance_pipeline_once(api, state, model_profile_id, event_rate_scheme_id, output_profile_id,
                                          vintage, geohaz_engine_type, geohaz_engine_version, hazard_layer_name)
            ss["pipeline_state"] = state
            if state["stage"] in ("done", "failed"):
                if state["stage"] == "done":
                    ss["auto_pull"] = True
                _save()
                st.rerun()                       # one full refresh so the buttons below update
        st.markdown(_tracker(_pipeline_rows(ss.get("rms_import_job"), state)), unsafe_allow_html=True)
        if state:
            with st.expander("Run log"):
                for line in state["log"]:
                    st.write(line)
    _live()

    if ps and ps.get("stage") == "done":
        st.success("The analysis has finished.")
        if st.button("View results", type="primary", key="to_results"):
            _goto(S_RES)
    elif ps and ps.get("stage") == "failed":
        st.error("The pipeline stopped - see the run log above for the reason.")

    if job:
        with st.expander("Start over"):
            st.caption(f"Clears this run so the files can be imported again. The EDM **{job['edm_name']}** already "
                       "exists in RMS, so use a new EDM name to avoid appending to it.")
            if st.button("Clear this run", key="run_clear"):
                for k in ("rms_import_job", "verify_result", "pipeline_state", "res_state", "verify_override", "launch_error"):
                    ss.pop(k, None)
                if ss.get("acct_id"):
                    STORE.clear_part(ss["acct_id"], "run")
                    STORE.clear_part(ss["acct_id"], "results")
                st.rerun()


# ==========================================================================
# EMAIL THE RESULTS - sent as the signed-in user (SSO) through Microsoft Graph, with an account summary in the body and
# the results attached. Three ways to sign in, tried in this order:
#   1. Posit Connect's Microsoft Graph integration  (the viewer's own SSO login; no extra sign-in)
#   2. A Microsoft device-code sign-in              (needs MS_CLIENT_ID + MS_TENANT_ID; one click, then SSO in a new tab)
#   3. MSGRAPH_TOKEN environment variable           (local testing only)
# If none is available the same email can always be downloaded as an Outlook draft (.eml) with the attachments
# already on it - open it in Outlook and press Send. Nothing is sent without pressing the button.
# ==========================================================================
GRAPH_URL = "https://graph.microsoft.com/v1.0"
MS_SCOPES = ("https://graph.microsoft.com/Mail.Send https://graph.microsoft.com/Mail.ReadWrite "
             "https://graph.microsoft.com/User.Read offline_access")
EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+'\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$")
INLINE_ATTACH_LIMIT = 2_500_000        # bytes; above this the attachment goes through an upload session
CHUNK = 3_932_160                      # 12 x 320 KiB, a safe size for every Graph upload endpoint
try:
    from rms_pdf import build_report_pdf as _build_pdf
except Exception:                                    # noqa: BLE001
    _build_pdf = None
try:
    from rms_workbook import build_workbook as _build_xlsx
except Exception:                                    # noqa: BLE001
    _build_xlsx = None
try:
    from rms_results_ui import TARGET_RP as _TARGET_RP
except Exception:                                    # noqa: BLE001
    _TARGET_RP = 250


# ---- sign-in -------------------------------------------------------------------------------------------------------
def _connect_error_text(exc) -> str:
    code = getattr(exc, "error_code", None)
    if code == 219:
        return "Your Microsoft sign-in with Posit Connect has expired. Log out of Connect and log back in, then try again."
    return f"Posit Connect could not give this app a Microsoft token ({type(exc).__name__}: {str(exc)[:160]})."


def _ms_connect_token() -> tuple:
    """-> (access_token, error). The viewer's own Microsoft token from Posit Connect's Microsoft Graph integration."""
    session_token = ""
    try:
        session_token = st.context.headers.get("Posit-Connect-User-Session-Token") or ""
    except Exception:                                # noqa: BLE001
        pass
    if not session_token:
        return "", "not_on_connect"
    try:                                             # the official SDK, when it is installed
        from posit import connect as _pc
        creds = _pc.Client().oauth.get_credentials(session_token)
        tok = (creds or {}).get("access_token", "")
        return (tok, "") if tok else ("", "Posit Connect returned no access token.")
    except ImportError:
        pass
    except Exception as exc:                         # noqa: BLE001
        return "", _connect_error_text(exc)
    server, key = os.environ.get("CONNECT_SERVER", "").rstrip("/"), os.environ.get("CONNECT_API_KEY", "")
    if not (server and key):
        return "", "Add posit-sdk to requirements.txt (or make CONNECT_SERVER / CONNECT_API_KEY available) so the app can read your Microsoft token."
    try:
        r = requests.post(f"{server}/__api__/v1/oauth/integrations/credentials", headers={"Authorization": f"Key {key}"},
                          data={"grant_type": "urn:ietf:params:oauth:grant-type:token-exchange",
                                "subject_token": session_token, "subject_token_type": "urn:posit:connect:user-session-token"},
                          timeout=20)
        if r.status_code == 200 and r.json().get("access_token"):
            return r.json()["access_token"], ""
        return "", f"Posit Connect refused the token request (HTTP {r.status_code}). Is the Microsoft Graph integration attached to this app?"
    except Exception as exc:                         # noqa: BLE001
        return "", f"Could not reach Posit Connect for a token ({type(exc).__name__})."


def _dev_cfg() -> tuple:
    return _secret("MS_TENANT_ID"), _secret("MS_CLIENT_ID")


def _dev_start() -> tuple:
    tenant, client = _dev_cfg()
    try:
        r = requests.post(f"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/devicecode",
                          data={"client_id": client, "scope": MS_SCOPES}, timeout=20)
        d = r.json()
        if r.status_code == 200 and d.get("device_code"):
            d["_t0"] = time.time()
            return d, ""
        return None, d.get("error_description", f"HTTP {r.status_code}").split("\r")[0][:220]
    except Exception as exc:                         # noqa: BLE001
        return None, f"{type(exc).__name__}: {exc}"


def _dev_poll(dev: dict) -> tuple:
    """One check. -> (token dict | None, 'ok' | 'pending' | error text)."""
    tenant, client = _dev_cfg()
    try:
        r = requests.post(f"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token",
                          data={"grant_type": "urn:ietf:params:oauth:grant-type:device_code", "client_id": client,
                                "device_code": dev["device_code"]}, timeout=20)
        d = r.json()
    except Exception as exc:                         # noqa: BLE001
        return None, f"{type(exc).__name__}: {exc}"
    if d.get("access_token"):
        d["expires_at"] = time.time() + int(d.get("expires_in", 3600)) - 60
        return d, "ok"
    if d.get("error") == "authorization_pending":
        return None, "pending"
    return None, (d.get("error_description") or d.get("error") or "sign-in failed").split("\r")[0][:220]


def _dev_refresh(tok: dict):
    tenant, client = _dev_cfg()
    try:
        r = requests.post(f"https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token",
                          data={"grant_type": "refresh_token", "client_id": client, "refresh_token": tok.get("refresh_token", ""),
                                "scope": MS_SCOPES}, timeout=20)
        d = r.json()
        if d.get("access_token"):
            d["expires_at"] = time.time() + int(d.get("expires_in", 3600)) - 60
            d.setdefault("refresh_token", tok.get("refresh_token"))
            return d
    except Exception:                                # noqa: BLE001
        pass
    return None


def _ms_mode() -> str:
    """Which sign-in is available right now (no network): 'device' (already signed in), 'env', 'connect', 'device_cfg', 'none'."""
    t = ss.get("ms_tok")
    if t and (t.get("expires_at", 0) > time.time() or t.get("refresh_token")):
        return "device"
    if os.environ.get("MSGRAPH_TOKEN"):
        return "env"
    try:
        if st.context.headers.get("Posit-Connect-User-Session-Token"):
            return "connect"
    except Exception:                                # noqa: BLE001
        pass
    tenant, client = _dev_cfg()
    return "device_cfg" if (tenant and client) else "none"


def _ms_token() -> tuple:
    """-> (access_token, error)."""
    mode = _ms_mode()
    if mode == "device":
        t = ss["ms_tok"]
        if t.get("expires_at", 0) <= time.time():
            t = _dev_refresh(t)
            if not t:
                ss.pop("ms_tok", None)
                return "", "Your Microsoft sign-in has expired. Sign in again."
            ss["ms_tok"] = t
        return t["access_token"], ""
    if mode == "env":
        return os.environ["MSGRAPH_TOKEN"], ""
    if mode == "connect":
        return _ms_connect_token()
    return "", "not_signed_in"


# ---- Graph calls ---------------------------------------------------------------------------------------------------------
def _graph_err(r) -> str:
    try:
        e = (r.json() or {}).get("error", {})
        txt = f"{e.get('code', '')}: {e.get('message', '')}".strip(": ")
    except Exception:                                # noqa: BLE001
        txt = (getattr(r, "text", "") or "")[:200]
    if r.status_code in (401, 403):
        return (f"Microsoft would not let this app send mail for you (HTTP {r.status_code}). The Microsoft Graph sign-in needs "
                f"the Mail.Send permission (and Mail.ReadWrite for attachments over 3 MB). {txt}")
    return f"HTTP {r.status_code} {txt}"


def _ms_whoami(tok: str) -> dict:
    try:
        r = requests.get(f"{GRAPH_URL}/me?$select=displayName,mail,userPrincipalName",
                         headers={"Authorization": f"Bearer {tok}"}, timeout=20)
        if r.status_code == 200:
            d = r.json()
            return {"name": d.get("displayName") or "", "mail": d.get("mail") or d.get("userPrincipalName") or ""}
    except Exception:                                # noqa: BLE001
        pass
    return {}


def _parse_addresses(text: str) -> tuple:
    """-> (valid list, invalid list). Accepts commas, semicolons, spaces and new lines; removes duplicates."""
    out, bad, seen = [], [], set()
    for part in re.split(r"[;,\s]+", text or ""):
        p = part.strip().strip("<>")
        if not p:
            continue
        if EMAIL_RE.match(p):
            if p.lower() not in seen:
                seen.add(p.lower())
                out.append(p)
        else:
            bad.append(p)
    return out, bad


def _file_att(name, data, mime) -> dict:
    return {"@odata.type": "#microsoft.graph.fileAttachment", "name": name, "contentType": mime,
            "contentBytes": base64.b64encode(data).decode("ascii")}


def _graph_send(tok: str, to: list, cc: list, subject: str, html_body: str, attachments: list) -> tuple:
    """Send as the signed-in user; it lands in their Sent Items. attachments = [(filename, bytes, mime)]. -> (ok, message)."""
    H = {"Authorization": f"Bearer {tok}", "Content-Type": "application/json"}
    msg = {"subject": subject, "body": {"contentType": "HTML", "content": html_body},
           "toRecipients": [{"emailAddress": {"address": a}} for a in to],
           "ccRecipients": [{"emailAddress": {"address": a}} for a in cc]}
    total = sum(len(b) for _n, b, _m in attachments)
    try:
        if total <= INLINE_ATTACH_LIMIT:
            msg["attachments"] = [_file_att(n, b, m) for n, b, m in attachments]
            r = requests.post(f"{GRAPH_URL}/me/sendMail", headers=H, json={"message": msg, "saveToSentItems": True}, timeout=120)
            return (True, "") if r.status_code in (200, 202) else (False, _graph_err(r))
        r = requests.post(f"{GRAPH_URL}/me/messages", headers=H, json=msg, timeout=60)      # big: draft -> attach -> send
        if r.status_code not in (200, 201):
            return False, _graph_err(r)
        mid = r.json()["id"]

        def _drop():
            try:
                requests.delete(f"{GRAPH_URL}/me/messages/{mid}", headers=H, timeout=20)
            except Exception:                        # noqa: BLE001
                pass
        for n, b, m in attachments:
            if len(b) <= INLINE_ATTACH_LIMIT:
                ra = requests.post(f"{GRAPH_URL}/me/messages/{mid}/attachments", headers=H, json=_file_att(n, b, m), timeout=120)
                if ra.status_code not in (200, 201):
                    _drop()
                    return False, f"Could not attach {n}: {_graph_err(ra)}"
                continue
            rs = requests.post(f"{GRAPH_URL}/me/messages/{mid}/attachments/createUploadSession", headers=H, timeout=60,
                               json={"AttachmentItem": {"attachmentType": "file", "name": n, "size": len(b), "contentType": m}})
            if rs.status_code not in (200, 201):
                _drop()
                return False, f"Could not start the upload of {n}: {_graph_err(rs)}"
            url = rs.json()["uploadUrl"]
            for start in range(0, len(b), CHUNK):                     # the upload URL is pre-authorised: no Authorization header
                part = b[start:start + CHUNK]
                rp = requests.put(url, data=part, timeout=300,
                                  headers={"Content-Length": str(len(part)), "Content-Type": "application/octet-stream",
                                           "Content-Range": f"bytes {start}-{start + len(part) - 1}/{len(b)}"})
                if rp.status_code not in (200, 201, 202):
                    _drop()
                    return False, f"Upload of {n} failed at byte {start} (HTTP {rp.status_code})."
        rsend = requests.post(f"{GRAPH_URL}/me/messages/{mid}/send", headers=H, timeout=60)
        if rsend.status_code in (200, 202):
            return True, ""
        _drop()
        return False, _graph_err(rsend)
    except Exception as exc:                         # noqa: BLE001
        return False, f"{type(exc).__name__}: {exc}"


# ---- the summary, the attachments, the draft file ---------------------------------------------------------------------
def _money(cur, v, dec=0) -> str:
    try:
        return f"{cur} {float(v):,.{dec}f}"
    except (TypeError, ValueError):
        return "-"


def _uk_date(iso) -> str:
    try:
        return datetime.fromisoformat(str(iso)[:10]).strftime("%d/%m/%Y")
    except Exception:                                # noqa: BLE001
        return str(iso or "")


def _email_summary(state: dict, edm_name: str) -> list:
    """The account summary as [(section, [(label, value), ...])]."""
    a = (ss.get("draft") or {}).get("account", {})
    sm = {}
    try:
        sm = _summarize_state(state) or {}
    except Exception:                                # noqa: BLE001
        pass
    cur = sm.get("currency") or (state.get("quote_data") or {}).get("currencyCode") or "USD"
    rp = sm.get("rp") or _TARGET_RP
    acct = [("Account", a.get("Account Key") or "-"), ("Layer", a.get("Layer Name") or state.get("layer") or "-")]
    for lbl, k in (("Underwriter", "Underwriter Initials"), ("Line of business", "Line of Business")):
        if a.get(k):
            acct.append((lbl, a[k]))
    if a.get("Inception Date") and a.get("Expiry Date"):
        acct.append(("Policy period", f"{_uk_date(a['Inception Date'])} to {_uk_date(a['Expiry Date'])}"))
    terms = []
    if a.get("Share %") not in (None, ""):
        terms.append(f"share {float(a['Share %']):g}%")
    for lbl, k in (("limit", "Policy Limit"), ("attachment", "Attachment")):
        if a.get(k):
            terms.append(f"{lbl} {_money(cur, a[k])}")
    if terms:
        acct.append(("Terms", ", ".join(terms)))
    if a.get("Premium"):
        acct.append(("Premium", _money(cur, a["Premium"])))
    exp = []
    if sm.get("locations"):
        exp.append(("Locations", f"{int(sm['locations']):,}"))
    if sm.get("tiv"):
        exp.append(("Total insured value", _money(cur, sm["tiv"])))
    res = []
    if sm.get("aal") is not None:
        res.append(("Quote AAL (gross)", _money(cur, sm["aal"])))
    if sm.get("mi_amt") is not None:
        pct = f"  ({sm['mi_pct'] * 100:+.2f}% of the in-force loss)" if sm.get("mi_pct") is not None else ""
        res.append((f"Marginal impact, 1 in {rp:,} OEP (gross)", _money(cur, sm["mi_amt"]) + pct))
        res.append(("In-force portfolio", _inforce_describe(state.get("inforce") or INFORCE)))
    elif state.get("mi_error"):
        res.append(("Marginal impact", "not calculated - " + str(state["mi_error"])[:160]))
    res.append(("Run", state.get("pulled_at") or "-"))
    ref = [("EDM", edm_name or "-"), ("Quote analysis ID", str(state.get("quote_id") or "-"))]
    return [("Account", acct), ("Exposure", exp), ("Results", res), ("Reference", ref)]


def _summary_html(sections, intro: str) -> str:
    e = _h.escape
    body = "".join(f"<p style='margin:0 0 6px'>{e(l)}</p>" if l.strip() else "<p style='margin:0 0 6px'>&nbsp;</p>"
                   for l in (intro or "").splitlines())
    rows = []
    for title, items in sections:
        if not items:
            continue
        rows.append(f"<tr><td colspan='2' style='padding:10px 0 3px;font-weight:700;color:#14304D;border-bottom:1px solid #14304D'>"
                    f"{e(title)}</td></tr>")
        for k, v in items:
            rows.append(f"<tr><td style='padding:3px 18px 3px 0;color:#555;white-space:nowrap'>{e(str(k))}</td>"
                        f"<td style='padding:3px 0'>{e(str(v))}</td></tr>")
    return ("<div style=\"font-family:'Segoe UI',Arial,sans-serif;font-size:14px;color:#1b1b1b\">" + body +
            "<table style='border-collapse:collapse;margin-top:6px;min-width:420px'>" + "".join(rows) + "</table>"
            "<p style='margin-top:16px;color:#777;font-size:12px'>Sent from ANV EQ Quote Desk. Results attached.</p></div>")


def _summary_text(sections, intro: str) -> str:
    out = [intro or "", ""]
    for title, items in sections:
        if items:
            out += [title.upper()] + [f"  {k}: {v}" for k, v in items] + [""]
    return "\n".join(out).rstrip() + "\n"


def _email_attachments(state: dict, edm_name: str, want_pdf: bool, want_xlsx: bool, want_csv: bool) -> tuple:
    """-> ([(filename, bytes, mime)], [problems]). Built from the same functions the Export tab uses; one failing
    attachment is reported and the others still go."""
    stamp = datetime.now().strftime("%Y%m%d_%H%M")
    key = re.sub(r"[^A-Za-z0-9._-]+", "_", str((ss.get("draft") or {}).get("account", {}).get("Account Key") or "account")).strip("_") or "account"
    atts, notes = [], []
    if want_pdf:
        try:
            if _build_pdf is None:
                raise RuntimeError("the PDF module did not load")
            atts.append((f"{key}_REPORT_{stamp}.pdf", _build_pdf(state, "GR", "OEP", _TARGET_RP, "pct", True, edm_name), "application/pdf"))
        except Exception as exc:                     # noqa: BLE001
            notes.append(f"PDF report not attached ({type(exc).__name__}: {str(exc)[:120]})")
    if want_xlsx:
        try:
            data = state.get("xlsx")
            if not data:
                if _build_xlsx is None:
                    raise RuntimeError("the workbook module did not load")
                data = _build_xlsx(state["bundle"])
            atts.append((f"{key}_RESULTS_{stamp}.xlsx", data,
                         "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
        except Exception as exc:                     # noqa: BLE001
            notes.append(f"Excel workbook not attached ({type(exc).__name__}: {str(exc)[:120]})")
    if want_csv:
        for nm, k in (("ACC", "acc_df"), ("LOC", "loc_df")):
            try:
                if k in ss:
                    atts.append((f"{key}_{nm}_{stamp}.csv", ss[k].to_csv(index=False).encode("utf-8"), "text/csv"))
            except Exception as exc:                 # noqa: BLE001
                notes.append(f"{nm} file not attached ({type(exc).__name__})")
    return atts, notes


def _build_eml(to: list, cc: list, subject: str, html_body: str, text_body: str, attachments: list) -> bytes:
    """An unsent Outlook draft (X-Unsent: 1) with the attachments on it - open it in Outlook and press Send."""
    from email.message import EmailMessage
    m = EmailMessage()
    m["Subject"] = subject
    if to:
        m["To"] = ", ".join(to)
    if cc:
        m["Cc"] = ", ".join(cc)
    m["X-Unsent"] = "1"
    m.set_content(text_body)
    m.add_alternative(html_body, subtype="html")
    for n, b, mime in attachments:
        mt, _, sub = mime.partition("/")
        m.add_attachment(b, maintype=mt, subtype=sub or "octet-stream", filename=n)
    return m.as_bytes()


def _fmt_size(n: int) -> str:
    return f"{n / 1_000_000:.1f} MB" if n >= 1_000_000 else f"{max(1, round(n / 1000))} KB"


# ---- the panel -------------------------------------------------------------------------------------------------------------------
def _email_panel(state: dict, edm_name: str) -> None:
    if not (state and state.get("stage") == "done"):
        return
    aid = ss.get("acct_id") or "new"
    a = (ss.get("draft") or {}).get("account", {})
    mode = _ms_mode()
    with st.expander("Email these results", expanded=bool(ss.get("em_open"))):
        if mode in ("connect", "env"):
            st.caption("Sends from your own Microsoft 365 mailbox, signed in with your SSO. A copy lands in your Sent Items.")
        elif mode == "device":
            who = ss["ms_tok"].get("who") or {}
            st.caption(f"Signed in as {who.get('name') or who.get('mail') or 'your Microsoft account'}. "
                       "A copy lands in your Sent Items.")
        else:
            st.caption("Microsoft sign-in is not set up for this app, so use the Outlook draft below - it opens in your own "
                       "Outlook with everything attached. See the note at the bottom to enable one-click sending.")
        c1, c2 = st.columns(2)
        to_txt = c1.text_input("To", key=f"em_to_{aid}", value=ss.get("em_last_to") or _secret("EMAIL_DEFAULT_TO"),
                               placeholder="name@company.com; name2@company.com")
        cc_txt = c2.text_input("Cc", key=f"em_cc_{aid}", value=ss.get("em_last_cc", ""))
        subject = st.text_input("Subject", key=f"em_sub_{aid}",
                                value=f"EQ quote results - {a.get('Account Key') or 'account'}"
                                      + (f" - {a.get('Layer Name')}" if a.get("Layer Name") else ""))
        intro = st.text_area("Message", key=f"em_msg_{aid}", height=110,
                             value=f"Hi,\n\nPlease find the EQ modelling results for {a.get('Account Key') or 'this account'} attached, "
                                   "with the account summary below.\n\nRegards")
        k1, k2, k3, k4 = st.columns(4)
        w_pdf = k1.checkbox("PDF report", value=True, key=f"em_pdf_{aid}")
        w_xlsx = k2.checkbox("Excel results", value=True, key=f"em_xlsx_{aid}")
        w_csv = k3.checkbox("ACC + LOC files", value=False, key=f"em_csv_{aid}")
        w_me = k4.checkbox("Copy me", value=True, key=f"em_me_{aid}", help="Adds your own address to Cc when you send.")
        sections = _email_summary(state, edm_name)
        with st.container(border=True):
            for title, items in sections:
                if items:
                    st.markdown(f"**{title}**  \n" + "  \n".join(f"{k}: {v}" for k, v in items))
        to, bad_to = _parse_addresses(to_txt)
        cc, bad_cc = _parse_addresses(cc_txt)
        for b_ in bad_to + bad_cc:
            st.warning(f"'{b_}' does not look like an email address.")
        # ---- sign-in (only when needed) ----
        if mode == "device_cfg":
            dev = ss.get("ms_dev")
            if not dev:
                if st.button("Sign in with Microsoft", key="em_signin"):
                    d, err = _dev_start()
                    if d:
                        ss["ms_dev"], ss["em_open"] = d, True
                    else:
                        ss["em_msg_state"] = ("error", f"Could not start sign-in: {err}")
                    st.rerun()
            else:
                st.info(f"1. Open {dev.get('verification_uri', 'https://microsoft.com/devicelogin')}  \n2. Enter the code "
                        f"**{dev['user_code']}** and sign in with your work account (your normal SSO).  \n3. Come back and press the button.")
                b1, b2 = st.columns(2)
                if b1.button("I have signed in", key="em_signed", type="primary"):
                    tok, status = _dev_poll(dev)
                    if tok:
                        tok["who"] = _ms_whoami(tok["access_token"])
                        ss["ms_tok"] = tok
                        ss.pop("ms_dev", None)
                        ss["em_msg_state"] = ("success", "Signed in.")
                    elif status == "pending":
                        ss["em_msg_state"] = ("info", "Microsoft has not seen the sign-in yet - finish it in the other tab, then press again.")
                    else:
                        ss["em_msg_state"] = ("error", f"Sign-in failed: {status}")
                        ss.pop("ms_dev", None)
                    ss["em_open"] = True
                    st.rerun()
                if b2.button("Cancel sign-in", key="em_cancel"):
                    ss.pop("ms_dev", None)
                    st.rerun()
        elif mode == "device" and st.button("Sign out of Microsoft", key="em_signout"):
            ss.pop("ms_tok", None)
            st.rerun()
        m_ = ss.pop("em_msg_state", None)
        if m_:
            {"success": st.success, "error": st.error, "info": st.info}.get(m_[0], st.info)(m_[1])

        can_send = mode in ("connect", "env", "device") and bool(to) and not bad_to and not bad_cc
        s1, s2 = st.columns(2)
        send = s1.button("Send email", key="em_send", type="primary", disabled=not can_send, width="stretch",
                         help=None if can_send else "Needs a Microsoft sign-in and at least one valid To address.")
        prep = s2.button("Prepare Outlook draft (.eml)", key="em_prep", width="stretch",
                         help="Builds the email with everything attached, ready to open in Outlook.")
        if send:
            with st.spinner("Building the attachments and sending..."):
                tok, terr = _ms_token()
                if not tok:
                    ss["em_result"] = ("error", terr if terr != "not_signed_in" else "Sign in with Microsoft first.")
                else:
                    atts, notes = _email_attachments(state, edm_name, w_pdf, w_xlsx, w_csv)
                    cc_all = list(cc)
                    if w_me:
                        me = _ms_whoami(tok).get("mail")
                        if me and me.lower() not in {x.lower() for x in to + cc_all}:
                            cc_all.append(me)
                    ok_, err_ = _graph_send(tok, to, cc_all, subject, _summary_html(sections, intro), atts)
                    if ok_:
                        ss["em_last_to"], ss["em_last_cc"] = ", ".join(to), ", ".join(cc)
                        ss.setdefault("em_log", []).append({"t": datetime.now().strftime("%d/%m/%Y %H:%M"), "to": to})
                        ss["em_result"] = ("success", f"Sent to {', '.join(to)} at {datetime.now():%H:%M} with "
                                           + (", ".join(f"{n} ({_fmt_size(len(b))})" for n, b, _m in atts) or "no attachments")
                                           + "." + (" Not attached: " + "; ".join(notes) if notes else ""))
                    else:
                        ss["em_result"] = ("error", "The email was NOT sent. " + err_ + " You can still download the Outlook draft below.")
            ss["em_open"] = True
            st.rerun()
        if prep:
            with st.spinner("Building the draft..."):
                atts, notes = _email_attachments(state, edm_name, w_pdf, w_xlsx, w_csv)
                sec = sections
                ss["em_eml"] = {"data": _build_eml(to, cc, subject, _summary_html(sec, intro), _summary_text(sec, intro), atts),
                                "name": f"{re.sub(r'[^A-Za-z0-9._-]+', '_', str(a.get('Account Key') or 'results'))}_email_draft.eml",
                                "notes": notes, "atts": [(n, len(b)) for n, b, _m in atts]}
            ss["em_open"] = True
            st.rerun()
        r_ = ss.pop("em_result", None)
        if r_:
            {"success": st.success, "error": st.error}.get(r_[0], st.info)(r_[1])
        eml = ss.get("em_eml")
        if eml:
            st.download_button("Download the Outlook draft", data=eml["data"], file_name=eml["name"], key="em_dl_eml",
                               mime="message/rfc822", type="primary" if mode == "none" else "secondary", width="stretch")
            st.caption("Open the downloaded file in Outlook, check it, and press Send. Attached: "
                       + (", ".join(f"{n} ({_fmt_size(sz)})" for n, sz in eml["atts"]) or "nothing")
                       + (". Not attached: " + "; ".join(eml["notes"]) if eml["notes"] else "") + ". "
                       "If you change the recipients or message above, prepare the draft again.")
        if ss.get("em_log"):
            last = ss["em_log"][-1]
            st.caption(f"Last sent from this session: {last['t']} to {', '.join(last['to'])}")
        if mode == "none":
            st.caption("To enable one-click sending with your SSO, ask the Connect administrator to attach a Microsoft Graph "
                       "integration (with Mail.Send) to this app, and add posit-sdk to requirements.txt. Or set MS_TENANT_ID and "
                       "MS_CLIENT_ID (an Entra app registration that allows public client flows) for a sign-in button.")


def _inforce_notice(state) -> None:
    """Which in-force portfolio Marginal Impact uses - and a warning if it could not run or saved results used another."""
    st.markdown(f"**In-force portfolio:** {_h.escape(_inforce_describe(INFORCE))}", unsafe_allow_html=False)
    if state and state.get("mi_error"):
        st.warning("Marginal impact could not be calculated, but everything else was pulled and saved. "
                   + str(state["mi_error"]) + " Pick the in-force portfolio at the top of the page, then open "
                   "**Refresh from RMS** below.")
    if not (state and state.get("stage") == "done"):
        return
    used = dict(state.get("inforce") or {})
    ids = _inforce_ids(used)
    for v in ((state.get("group") or {}).get("portfolio_id"),
              ((state.get("bundle") or {}).get("mi") or {}).get("portfolio_id")):
        if v:
            ids.add(str(v))
    if not ids:
        return                                                  # Marginal Impact was not run for this account
    if ids & _inforce_ids(INFORCE):
        return
    what = _inforce_describe(used) if used else "analysis " + ", ".join(sorted(ids))
    st.warning(f"These saved results compare against a different in-force portfolio ({what}). To re-run Marginal "
               "Impact against the one selected at the top of the page, open **Refresh from RMS** below.")


# ---- Step 4: results ----------------------------------------------------------------
def _step_results():
    if render_results is None:
        st.error(f"The results module could not load - {_step6_error}")
        return
    job = ss.get("rms_import_job")
    state = ss.get("res_state")
    pstate = ss.get("pipeline_state") or {}
    have_results = bool(state and state.get("stage") == "done")
    # saved results are shown even if the run record is missing - they must never be hidden by an unrelated gap
    ready = have_results or bool(job and (job.get("recovered") or pstate.get("stage") == "done"))
    if not ready:
        st.info("Results appear here once the analysis in step 3 has finished.")
        if job and st.button("Go to the RMS run", key="res_to_run"):
            _goto(S_RUN)
        return

    def _done(new_state):
        if new_state.get("group") and not new_state.get("inforce"):
            new_state["inforce"] = {k: v for k, v in INFORCE.items() if k in ("as_at", "id", "app_id", "analysis_id", "name")}
            new_state["inforce"]["default"] = bool(INFORCE.get("default"))
        _inforce_learn(new_state)                      # remember the long ID RMS used for this month
        _save(include_results=True)                    # never raises: a failed save cannot wipe the results screen

    kw = dict(host=host, li_api_key=api_key, risk_api_key=rms_import_api_key, grouping_api_key=grouping_api_key,
              grouping_rg_id=grouping_rg_id, inforce_id=inforce_analysis_id, verify=verify_ssl,
              account_key=ss["draft"]["account"]["Account Key"], loc_df=ss.get("loc_df"), job=job or {"edm_name": ""},
              pstate=pstate, on_done=_done)
    _inforce_notice(state)
    if have_results:
        note = f"Saved {_uk(state['from_library'])}" if state.get("from_library") else ""
        try:
            render_results(state, (job or {}).get("edm_name", ""), note)
        except Exception as exc:                       # noqa: BLE001
            if type(exc).__name__ in ("RerunException", "StopException"):
                raise
            st.error("These saved results could not be displayed. The stored copy has NOT been changed.")
            st.code(f"{type(exc).__name__}: {exc}", language=None)
            if job and st.button("Rebuild the results from RMS", key="res_rebuild", type="primary"):
                ss.pop("res_state", None)
                ss["auto_pull"] = True
                st.rerun()
        try:
            _email_panel(state, (job or {}).get("edm_name", ""))
        except Exception as exc:                       # noqa: BLE001
            if type(exc).__name__ in ("RerunException", "StopException"):
                raise
            st.warning(f"The email panel hit a problem ({type(exc).__name__}: {str(exc)[:160]}). The results are not affected.")
        if ss.get("acct_id"):
            try:
                _bk = STORE.export_one_bytes(ss["acct_id"])
                if _bk:
                    st.download_button("Download a backup file of this account", data=_bk, key="bk_dl_acct",
                                       file_name=f"ANV_{(ss['draft']['account'].get('Account Key') or 'account')}_{datetime.now():%Y%m%d_%H%M}.json",
                                       mime="application/json",
                                       help="Restore it any time from the Accounts page (Restore from a backup file).")
            except Exception:                           # noqa: BLE001
                pass
        with st.expander("Refresh from RMS"):
            render_pull_panel(auto=False, **kw)
    else:
        render_pull_panel(auto=bool(ss.pop("auto_pull", False)), **kw)


# ---- workspace shell ------------------------------------------------------------------
def _workspace_view():
    _rs = ss.get("res_state")                            # safety net: results on screen are always written to the library
    if _rs and _rs.get("stage") == "done" and not _rs.get("_persisted") and time.time() >= ss.get("_persist_retry_at", 0):
        _save(include_results=True)
        if not _rs.get("_persisted"):
            ss["_persist_retry_at"] = time.time() + 20
    _storage_banner()
    a = ss["draft"]["account"]
    status = _derive_status()
    title = _h.escape(a["Account Key"] or "New quote")
    st.markdown(f'<div class="pg-title">{title}{_badge(status)}{_save_badge()}</div>'
                f'<div class="pg-sub">{_h.escape(a["Layer Name"]) + " &middot; " if a["Layer Name"] else ""}'
                f'{_h.escape(a["Line of Business"]) + " &middot; " if a["Line of Business"] else ""}'
                f'{datetime.fromisoformat(a["Inception Date"]):%d/%m/%Y} to {datetime.fromisoformat(a["Expiry Date"]):%d/%m/%Y}'
                f'</div>', unsafe_allow_html=True)

    _si = ss.get("save_info")
    if _si and not _si.get("ok"):
        st.error("This account could not be saved, so it may not be there next time: " + (_si.get("error") or "unknown error")
                 + ". Your work is still on screen and will be retried; if this stays, tell me the message.")
    _on = ss.get("open_notice")
    if _on:
        if _rs and _rs.get("stage") == "done":
            ss.pop("open_notice", None)
        else:
            st.warning(_on)
    if "ws_step_req" in ss:
        ss["ws_step"] = ss.pop("ws_step_req")
    ss.setdefault("ws_step", S_QUOTE)
    if hasattr(st, "segmented_control"):
        pick = st.segmented_control("Step", SECTION_STEPS, key="ws_step", label_visibility="collapsed")
    else:
        pick = st.radio("Step", SECTION_STEPS, key="ws_step", horizontal=True, label_visibility="collapsed")
    if pick is None:                         # clicking the active step again would clear it - put it back
        ss["ws_step_req"] = ss.get("_last_step", S_QUOTE)
        st.rerun()
    step = pick
    ss["_last_step"] = step
    st.markdown("")

    if step == S_QUOTE:
        _step_quote()
    elif step == S_GEO:
        _step_geocode()
    elif step == S_RUN:
        _step_run()
    else:
        _step_results()


if ss.get("view") == "library":
    _library_view()
else:
    _workspace_view()
